import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.BN3Eol-0.js";const u=JSON.parse('{"title":"UXS-004 — Mission Library","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/UXS-004.md","filePath":"uxs/UXS-004.md"}'),s={name:"uxs/UXS-004.md"};function r(n,e,l,c,d,h){return t(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="uxs-004-—-mission-library" tabindex="-1">UXS-004 — Mission Library <a class="header-anchor" href="#uxs-004-—-mission-library" aria-label="Permalink to &quot;UXS-004 — Mission Library&quot;">​</a></h1><blockquote><p>Status · Draft v0.1 Visual fidelity · Verified against prototype (P04_mission-library.html) IA anchor · §surfaces/missions · §topbar-patterns · §shared-tokens Related PRD · PRD-004 Related RFCs · RFC-002 (mission schema), RFC-004 (URL params)</p></blockquote><h2 id="why-this-uxs-exists" tabindex="-1">Why this UXS exists <a class="header-anchor" href="#why-this-uxs-exists" aria-label="Permalink to &quot;Why this UXS exists&quot;">​</a></h2><p>The mission library is the most HTML-intensive screen — a card grid, filter bar, and detail panel. This UXS defines the card appearance, agency colour system, filter states, and detail panel content layout.</p><h2 id="principles" tabindex="-1">Principles <a class="header-anchor" href="#principles" aria-label="Permalink to &quot;Principles&quot;">​</a></h2><ul><li>Agency colour is the dominant identity signal on each card</li><li>The &quot;first&quot; line earns the click — it must be readable at card size</li><li>Filter state is immediately obvious</li><li>The detail panel tells the mission&#39;s story before it lists its data</li></ul><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>In scope: nav bar, filter bar, card grid, card states, detail panel (OVERVIEW, GALLERY, LEARN tabs), agency logo treatment. Non-goals: card sort order, filter animation. Boundary note: Gallery image loading from NASA API belongs in the screen module.</p><h2 id="theme" tabindex="-1">Theme <a class="header-anchor" href="#theme" aria-label="Permalink to &quot;Theme&quot;">​</a></h2><p>Dark only.</p><h2 id="tokens" tabindex="-1">Tokens <a class="header-anchor" href="#tokens" aria-label="Permalink to &quot;Tokens&quot;">​</a></h2><h3 id="inherited-from-ia" tabindex="-1">Inherited from IA <a class="header-anchor" href="#inherited-from-ia" aria-label="Permalink to &quot;Inherited from IA&quot;">​</a></h3><p>All shared tokens, agency colour tokens.</p><h3 id="defined-here" tabindex="-1">Defined here <a class="header-anchor" href="#defined-here" aria-label="Permalink to &quot;Defined here&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>card-bg:          rgba(8,8,24,0.95)</span></span>
<span class="line"><span>card-border:      rgba(255,255,255,0.06)</span></span>
<span class="line"><span>card-border-hover: rgba(255,255,255,0.15)</span></span>
<span class="line"><span>card-selected:    1px solid [agency-color], box-shadow 0 0 20px [agency-color]22</span></span>
<span class="line"><span>filter-active:    rgba(80,112,255,0.25) bg, rgba(80,112,255,0.5) border</span></span>
<span class="line"><span>filter-inactive:  transparent bg, rgba(255,255,255,0.1) border</span></span></code></pre></div><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><h3 id="filter-bar-below-nav-40px" tabindex="-1">Filter bar (below nav, 40px) <a class="header-anchor" href="#filter-bar-below-nav-40px" aria-label="Permalink to &quot;Filter bar (below nav, 40px)&quot;">​</a></h3><p>Two filter groups: DESTINATION (ALL / MARS / MOON) and STATUS (ALL / ACTIVE / FLOWN / PLANNED). Each filter option is a <code>&lt;Chip kind=&quot;choice&quot;&gt;</code> (UXD-014).</p><h3 id="card-grid" tabindex="-1">Card grid <a class="header-anchor" href="#card-grid" aria-label="Permalink to &quot;Card grid&quot;">​</a></h3><p>Responsive: 3 columns at full width. Each card ~200px wide. Card contains:</p><ul><li>Agency logo top-left (40px)</li><li>Agency colour accent bar left edge (4px)</li><li>Mission name: Bebas Neue 22px</li><li>Type line: Space Mono 11px, <code>rgba(255,255,255,0.6)</code></li><li>Year: Space Mono 11px, <code>rgba(255,255,255,0.6)</code></li><li>&quot;First&quot; line: Space Mono 11px, <code>rgba(255,255,255,0.7)</code></li></ul><h3 id="detail-panel-right-340px" tabindex="-1">Detail panel (right, 340px) <a class="header-anchor" href="#detail-panel-right-340px" aria-label="Permalink to &quot;Detail panel (right, 340px)&quot;">​</a></h3><p>Same panel component as explore screen. Three tabs: OVERVIEW, GALLERY, LEARN.</p><p>OVERVIEW contains:</p><ul><li>Mission header (agency, name, type, status badge)</li><li>Data grid (departure, arrival, transit, vehicle, payload, delta-v)</li><li>Editorial description (Space Mono upright, 16px lead (15px on phones), shared <code>.editorial</code>)</li><li>&quot;Road to Mars&quot; or &quot;Capability&quot; contextual block (left-border accent)</li><li>FLY THIS MISSION button (if applicable)</li></ul><p>GALLERY: image grid from NASA Images API, 2 columns, captions below each.</p><p>LEARN: tiered links (INTRO muted blue, CORE blue, DEEP orange).</p><h2 id="component-states" tabindex="-1">Component states <a class="header-anchor" href="#component-states" aria-label="Permalink to &quot;Component states&quot;">​</a></h2><p><strong>Card (default):</strong> <code>card-bg</code>, <code>card-border</code>, hover lifts slightly <strong>Card (hovered):</strong> <code>card-border-hover</code>, subtle shadow <strong>Card (selected):</strong> agency-colour border, panel open <strong>Filter chip (active):</strong> <code>filter-active</code><strong>Filter chip (inactive):</strong> <code>filter-inactive</code><strong>Status badge (ACTIVE):</strong> green tint background, &quot;ACTIVE&quot; text <strong>Status badge (FLOWN):</strong> neutral, &quot;FLOWN&quot; <strong>Status badge (PLANNED):</strong> blue tint, &quot;PLANNED&quot; <strong>Data quality badge (partial/reconstructed):</strong> amber, shown in panel header <strong>FLY button (enabled):</strong> same as configurator FLY button <strong>Gallery image (loading):</strong> grey placeholder rect with spinner <strong>Gallery image (loaded):</strong> image with caption below</p><h2 id="accessibility" tabindex="-1">Accessibility <a class="header-anchor" href="#accessibility" aria-label="Permalink to &quot;Accessibility&quot;">​</a></h2><ul><li>Cards: <code>role=&quot;button&quot;</code> or <code>&lt;button&gt;</code>, keyboard navigable, enter to select</li><li>Filter chips (UXD-014): <code>role=&quot;radio&quot;</code> in a <code>role=&quot;radiogroup&quot;</code> per filter group</li><li>Detail panel: semantic headings, screen-reader accessible</li></ul><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><blockquote><p><strong>As-built note (2026-10-16):</strong> the boxes below were not maintained after implementation and are not a record of what shipped. For shipped behaviour see <a href="./../adr/TA"><code>docs/adr/TA.md</code></a> and <a href="./../../CHANGELOG"><code>CHANGELOG.md</code></a>.</p></blockquote><ul><li>[ ] All 32 mission cards visible, correctly coloured by agency</li><li>[ ] MARS filter shows 16 cards; MOON filter shows 16 cards</li><li>[ ] ACTIVE filter shows only active missions</li><li>[ ] Selected card has agency-colour border</li><li>[ ] Detail panel opens on card click</li><li>[ ] OVERVIEW tab shows all mission data fields</li><li>[ ] GALLERY tab shows NASA Images API results or placeholder</li><li>[ ] LEARN tab shows tiered links in three colour tiers</li><li>[ ] FLY THIS MISSION button present for missions with arc data</li><li>[ ] FLY button navigates to <code>/fly?mission=[id]</code></li></ul><hr><h2 id="extension-—-flight-tab-v0-1-7-adr-027-and-the-era-strip-uxd-048" tabindex="-1">Extension — FLIGHT tab (v0.1.7 / ADR-027) and the era strip (UXD-048) <a class="header-anchor" href="#extension-—-flight-tab-v0-1-7-adr-027-and-the-era-strip-uxd-048" aria-label="Permalink to &quot;Extension — FLIGHT tab (v0.1.7 / ADR-027) and the era strip (UXD-048)&quot;">​</a></h2><p>Two surfaces on /missions: a per-mission <strong>FLIGHT</strong> tab in the detail panel, and the <strong>era strip</strong> at the top of the screen (the v0.1.7 timeline navigator was replaced, see below).</p><h3 id="flight-tab-mission-detail-panel" tabindex="-1">FLIGHT tab (mission detail panel) <a class="header-anchor" href="#flight-tab-mission-detail-panel" aria-label="Permalink to &quot;FLIGHT tab (mission detail panel)&quot;">​</a></h3><p>Sits between OVERVIEW and GALLERY. Two-column layout on desktop (≥768 px), stacked on mobile. Sections:</p><ul><li><strong>Caveat banner</strong> (only when <code>flight_data_quality !== &quot;measured&quot;</code>) — amber, one-line plain-language (&quot;Reconstructed flight data — values approximate&quot;).</li><li><strong>LAUNCH</strong> — vehicle stage, C3 (km²/s²), declination (°), mass at TLI/TMI (kg), source citation.</li><li><strong>CRUISE</strong> — TCM count, peak heliocentric speed (km/s), source.</li><li><strong>ARRIVAL</strong> — V∞ (km/s), entry/orbital geometry (periapsis km / inclination °), orbit-insertion ∆v (km/s), source.</li><li><strong>TOTALS</strong> — total mission ∆v, TLI/TMI ∆v breakdown, source.</li><li><strong>EVENTS</strong> — MET-stamped list, each row: <code>T+nnnd · TYPE · note</code>. Note text comes from i18n overlay; type is enum.</li></ul><p>Each section is collapsible on mobile (initially open). Missing values render as <code>—</code>. Each subsection&#39;s <code>source</code> shows as a small upright source line (11–12 px, label colour) under the section&#39;s last value.</p><h3 id="era-strip-agency-filter-and-cards-uxd-048" tabindex="-1">Era strip, agency filter and cards (UXD-048) <a class="header-anchor" href="#era-strip-agency-filter-and-cards-uxd-048" aria-label="Permalink to &quot;Era strip, agency filter and cards (UXD-048)&quot;">​</a></h3><p>Replaces the &quot;timeline navigator&quot; of v0.1.7 (year drag handles, <code>?from=&amp;to=</code>, agency dots on a year axis), which was swapped for the epoch strip on 2026-06-17 and is rebuilt here. All three sit above the grid and are visible without opening FILTERS:</p><ul><li><strong>Era strip</strong>: nine equal tiles (<code>EpochTimelineStrip</code>), each a flagship mission photo under a dark gradient with the era name, years, count and one dot per active agency (palette, Design System §2.4). A radiogroup: click or Enter/Space chooses, the chosen tile again clears; arrow keys, Home and End move (reversed in right-to-left). URL <code>?epoch=&lt;era-id&gt;</code> (unchanged; an unknown id falls back to all). Nine columns at a strip of 1100 px or more, five and four below, one scroll row under 560 px. The chosen tile has the #889fe7 edge.</li><li><strong>Agency filter</strong>: one chip per agency with a palette dot (10 px), its name and its mission count; no logo. FILTERS holds destination, status and crew.</li><li><strong>Toolbar</strong> (shared with /fleet): the catalogue total, &quot;<code>Showing: &lt;era&gt; (&lt;n&gt;)</code>&quot;, the sort select (newest, oldest, alphabetical; <code>?sort=</code>) and Grid / List (<code>?view=list</code>).</li><li><strong>Card</strong>: the shared <code>EntityCard</code>: photo, name and year, one line per agency (bar in its colour), status pill, story, one fixed footprint. Spec: Design System §5.4, §5.7a.</li></ul><h3 id="tokens-extension" tabindex="-1">Tokens (extension) <a class="header-anchor" href="#tokens-extension" aria-label="Permalink to &quot;Tokens (extension)&quot;">​</a></h3><p><strong>FLIGHT tab section header:</strong> Bebas Neue, 14 px, <code>rgba(220,230,255,0.95)</code>, letter-spacing 0.08 em <strong>FLIGHT tab value:</strong> Space Mono, 13 px, <code>#fff</code><strong>FLIGHT tab source line:</strong> Space Mono upright, 11 px (label floor), <code>rgba(180,200,255,0.6)</code><strong>FLIGHT tab caveat banner:</strong> <code>#ffc850</code> border 1 px, <code>rgba(255,200,80,0.18)</code> bg, 12 px Space Mono</p><h3 id="accessibility-extension" tabindex="-1">Accessibility (extension) <a class="header-anchor" href="#accessibility-extension" aria-label="Permalink to &quot;Accessibility (extension)&quot;">​</a></h3><ul><li>FLIGHT tab: each subsection uses <code>&lt;section&gt;</code> with <code>&lt;h3&gt;</code> heading; <code>&lt;dl&gt;</code>/<code>&lt;dt&gt;</code>/<code>&lt;dd&gt;</code> for key-value rows so screen readers traverse coherently.</li></ul><h3 id="acceptance-criteria-extension" tabindex="-1">Acceptance criteria (extension) <a class="header-anchor" href="#acceptance-criteria-extension" aria-label="Permalink to &quot;Acceptance criteria (extension)&quot;">​</a></h3><ul><li>[ ] FLIGHT tab visible only when mission has <code>flight</code> data; falls back gracefully when absent</li><li>[ ] Sparse-data banner shown only when <code>flight_data_quality !== &quot;measured&quot;</code></li><li>[ ] All numeric values render as <code>—</code> when missing — never <code>0</code> or <code>undefined</code></li><li>[ ] Source citations visible per subsection</li><li>[ ] Events list shows MET-stamped entries with i18n notes</li><li>[ ] URL syncs <code>?from=YYYY&amp;to=YYYY</code>; deep-link restores the window</li><li>[ ] Mobile pinch-to-zoom expands the strip; two-finger pan slides</li><li>[ ] Reduced-motion variant: number inputs replace the strip</li><li>[ ] Mission-dot tap highlights + opens detail panel</li><li>[ ] No regression on existing OVERVIEW / GALLERY / LEARN tabs</li></ul><h2 id="extension-—-fleet-fleet-uxd-035" tabindex="-1">Extension — Fleet (<code>/fleet</code>, UXD-035) <a class="header-anchor" href="#extension-—-fleet-fleet-uxd-035" aria-label="Permalink to &quot;Extension — Fleet (\`/fleet\`, UXD-035)&quot;">​</a></h2><p><code>/fleet</code> is the sibling of the mission library and shares its filter chrome (FILTERS strip, UXD-014). Two rules on top of it:</p><ul><li><strong>View toggle.</strong> A GRID / LINE-UP choice radiogroup on the FILTERS row, right after FILTERS; Launchers and Capsules &amp; spacecraft appear after it only in LINE-UP (<code>?view=lineup&amp;kind=</code>). FILTERS is disabled, not removed, while LINE-UP is on; GRID returns with the filters as they were. The era strip of E3 goes inside the filters panel, so it does not move the toggle.</li><li><strong>Missions tab.</strong> One tab, MISSIONS, for every entry with 2 or more missions: the union of its flights and linked missions, oldest first. A row is a link with a round photo only where the mission exists; the others are plain text. The crew of a flight is one line of names. The OVERVIEW button shows the same count, or the mission&#39;s name when there is one.</li></ul><p>Acceptance:</p><ul><li>[ ] Crew Dragon: 5 rows, 2 links, no portrait or placeholder; Gemini 10 rows, 6 links; Soyuz 7K-OK 7 rows, 3 links</li><li>[ ] Every link in the tab opens a mission that exists; the OVERVIEW count equals the number of rows</li><li>[ ] The view radiogroup has a name; arrow keys move between GRID and LINE-UP; 0 serious axe violations with the line-up on and with the tab open</li></ul><h3 id="acceptance-criteria-era-strip-uxd-048" tabindex="-1">Acceptance criteria (era strip, UXD-048) <a class="header-anchor" href="#acceptance-criteria-era-strip-uxd-048" aria-label="Permalink to &quot;Acceptance criteria (era strip, UXD-048)&quot;">​</a></h3><ul><li>[ ] Nine tiles, each with a photo, name, years, count; counts add up to the catalogue</li><li>[ ] Arrow keys select and move focus; reversed in Arabic; the tile order mirrors in Arabic</li><li>[ ] No label clipped in en, de, ar at 1440, 768 and 390 px; one scroll row at 390 px</li><li>[ ] Every agency chip has a palette dot and a count; card agency bars use the same colours</li></ul><h2 id="extension-—-the-same-pattern-on-programs-and-missions-launches-uxd-048-round-4" tabindex="-1">Extension — the same pattern on /programs and /missions/launches (UXD-048, round 4) <a class="header-anchor" href="#extension-—-the-same-pattern-on-programs-and-missions-launches-uxd-048-round-4" aria-label="Permalink to &quot;Extension — the same pattern on /programs and /missions/launches (UXD-048, round 4)&quot;">​</a></h2><p>Neither page has a UXS of its own (their specs are PRD-029 and PRD-020/RFC-023); the pattern above is their screen contract, with these differences:</p><ul><li><strong>/programs</strong>: the title, lead and patch wall stay above the tools. Era = the program&#39;s start year; agency chips by agency; FILTERS holds the kind; the card is a link (kind pill first, then status); <code>?epoch= &amp;agency= &amp;kind= &amp;q= &amp;sort= &amp;view=list</code>.</li><li><strong>/missions/launches</strong>: opens as the month-grouped list (List is the default, Grid is <code>?view=grid</code>); era by launch year with counts from <code>launches-years.json</code>, an era loads the decades it spans; provider chips by short name; FILTERS holds view, tier, decade, outcome and year; all of <code>?mode= &amp;decade= &amp;tier= &amp;agency= &amp;outcome= &amp;year=</code> as before, plus <code>?epoch= &amp;q= &amp;sort= &amp;view=</code>.</li></ul><p>Acceptance:</p><ul><li>[ ] The parts come in one order on both pages: search, strip, agency row, toolbar, content</li><li>[ ] /programs: every card the same size (287 px at 1440), each a link; the kind pill whole; the era tiles add up to the catalogue</li><li>[ ] /missions/launches: List is on at first load; Grid cards are one size; every old parameter still filters; an era tile&#39;s count equals the launches that era shows</li></ul>`,62)])])}const g=a(s,[["render",r]]);export{u as __pageData,g as default};
